{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history includes positive sentiment (e.g., >0.00) and model overestimates prices, especially after recent spikes.",
    "Reduce forecast magnitude when true outcomes show strong mean reversion toward lower levels after sustained high prices.",
    "Apply a lag correction: if true outcome is significantly lower than forecast, reduce forecast by 5-10% for the next period to account for delayed market reaction.",
    "Increase forecast sensitivity to sentiment history: if sentiment is negative (e.g., <0.00), apply a downward bias of 3-5% to model output.",
    "Cap forecast growth after a spike: if model forecasts >10% above recent high, reduce by 15-20% to prevent overshoot.",
    "Use recent true outcome as anchor: if model forecast deviates >10% from last 5-day average true outcome, adjust toward that average."
  ]
}
